$Model = [ordered]@{}
function Add-Entity($Domain, $Name, $Columns, $Checks = @(), $Indexes = @(), $Mode = 'mutable') {
	$Model[$Name] = @{ Domain = $Domain; Name = $Name; Columns = $Columns; Checks = $Checks; Indexes = $Indexes; Mode = $Mode }
}
